    "project_featured_media": "https://inidesignstudio.com/wp-content/uploads/2023/02/Devotional-Conflict-Meera-to-Radha-Textile-Cover-Image.jpeg",
    "project_slug": "devotional-conflict-meera-to-radha-2",
