    "project_image_5": "https://inidesignstudio.com/wp-content/uploads/2020/11/2014.10.17_AUDA-AUHC-fianl-ppt-135-scaled.jpg",
    "project_image_6": "https://inidesignstudio.com/wp-content/uploads/2020/11/2014.10.17_AUDA-AUHC-fianl-ppt-136-scaled.jpg",
